def is_subset(set1, set2):
    # Validate that both inputs are sets
    if not isinstance(set1, set) or not isinstance(set2, set):
        raise TypeError("Both inputs must be sets.")

    # Validate that all elements in both sets are numbers
    for item in set1:
        if not isinstance(item, (int, float)):
            raise TypeError("All elements in set1 must be numbers.")
    for item in set2:
        if not isinstance(item, (int, float)):
            raise TypeError("All elements in set2 must be numbers.")

    # Check if set1 is a subset of set2 without using built-in set comparison functions
    # An empty set is a subset of any set, including itself
    if len(set1) == 0:
        return True

    for element in set1:
        if element not in set2:
            return False

    return True
