def increment_leaf_values(nested_dict):
    """
    Recursively increments all leaf values in a nested dictionary by 1.

    Parameters:
        nested_dict (dict): A dictionary potentially containing nested dictionaries.

    Returns:
        dict: A new dictionary with all leaf values incremented by 1.

    Raises:
        TypeError: If the input is not a dictionary or if any value is not a dict or a valid leaf type.
        ValueError: If a leaf value is not a number (int or float).
    """
    if not isinstance(nested_dict, dict):
        raise TypeError(f"Expected a dictionary, but got {type(nested_dict).__name__}.")

    result = {}

    for key, value in nested_dict.items():
        if isinstance(value, dict):
            # Recursively process nested dictionaries
            result[key] = increment_leaf_values(value)
        elif isinstance(value, (int, float)):
            # Increment numeric leaf values
            result[key] = value + 1
        else:
            # Treat non-dict, non-numeric values as leaves (e.g., strings, booleans)
            # We still increment them by 1 if they are numeric-like, otherwise keep as is.
            # However, to strictly follow "leaf value incremented by 1", we assume only numbers are valid leaves.
            if not isinstance(value, (int, float)):
                raise ValueError(
                    f"Leaf value for key '{key}' is not a number (int or float). "
                    f"Got {type(value).__name__} with value: {value!r}. "
                    "Only numeric leaf values can be incremented."
                )
            result[key] = value + 1

    return result


