class DynamicModuleError(Exception):
    """Custom exception for dynamic module loading and function calling errors."""
    def __init__(self, module_name, function_name, message):
        self.module_name = module_name
        self.function_name = function_name
        super().__init__(f"Error in module '{module_name}' function '{function_name}': {message}")


def dynamic_module_func(module_name, function_name, *args, **kwargs):
    """
    Dynamically loads a Python module and calls a specified function within it.

    Args:
        module_name (str): The name of the module to import.
        function_name (str): The name of the function to call within the module.
        *args: Positional arguments to pass to the function.
        **kwargs: Keyword arguments to pass to the function.

    Returns:
        The result of the function call.

    Raises:
        DynamicModuleError: If module loading, function retrieval, or function execution fails.
    """
    try:
        module = __import__(module_name)
    except ImportError as e:
        raise DynamicModuleError(module_name, function_name, f"Failed to import module: {e}") from e

    try:
        func = getattr(module, function_name)
    except AttributeError as e:
        raise DynamicModuleError(module_name, function_name, f"Function '{function_name}' not found in module: {e}") from e

    try:
        if not callable(func):
            raise TypeError(f"'{function_name}' is not callable in module '{module_name}'")
        return func(*args, **kwargs)
    except Exception as e:
        raise DynamicModuleError(module_name, function_name, f"Execution failed: {e}") from e
