def get_env_var_dict(env_var_file):
    """
    Retrieves a dictionary of environment variables from a specified environment variable file.

    The file format is key=value, one per line.
    - Returns an empty dictionary if the file does not exist.
    - Excludes any key-value pairs where the value is empty.

    :param env_var_file: Path to the environment variable file.
    :return: Dictionary of environment variables (key: str, value: str), or empty dict if file missing or invalid.
    """
    result = {}

    try:
        with open(env_var_file, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue

                if '=' not in line:
                    continue

                key, _, value = line.partition('=')
                key = key.strip()
                value = value.strip()

                if key and value:
                    result[key] = value
    except FileNotFoundError:
        return {}
    except Exception:
        return {}

    return result
