from typing import List, Optional

def shell_quote(args: List[Optional[str]]) -> str:
    def quote(s: Optional[str]) -> str:
        if s is None:
            return "''"
        # Check if quoting is necessary
        needs_quote = False
        for ch in s:
            if ch in '"\'$`!&|;()[]{}<>\\':
                needs_quote = True
                break
            if ch == '\n' or ch == '\r':
                needs_quote = True
                break
        if not needs_quote:
            return s
        # Escape single quotes by ending the string, adding an escaped single quote, and starting again
        result = []
        for ch in s:
            result.append(ch)
            if ch == "'":
                result.append("'\\''")
        return "'" + "".join(result) + "'"

    return " ".join(quote(arg) for arg in args)
