def average_value(values):
    if not values:
        return 0
    total = sum(values)
    count = len(values)
    average = total / count
    # Round to nearest integer, with ties going to the larger value
    # This is equivalent to adding 0.5 and using floor for positive numbers,
    # but we need to handle negative numbers correctly for "round half up" behavior.
    # Python's round() uses "round half to even", so we implement custom rounding.
    if average >= 0:
        return int(average + 0.5)
    else:
        return int(average - 0.5)
