def check_sudoku(board):
    # Check rows
    for row in board:
        seen = set()
        for num in row:
            if num == 0:
                continue
            if num in seen:
                return False
            seen.add(num)
        if len(seen) != 9:
            return False

    # Check columns
    for col_idx in range(9):
        seen = set()
        for row_idx in range(9):
            num = board[row_idx][col_idx]
            if num == 0:
                continue
            if num in seen:
                return False
            seen.add(num)
        if len(seen) != 9:
            return False

    # Check 3x3 sub-boxes
    for box_row in range(3):
        for box_col in range(3):
            seen = set()
            for i in range(3):
                for j in range(3):
                    num = board[box_row * 3 + i][box_col * 3 + j]
                    if num == 0:
                        continue
                    if num in seen:
                        return False
                    seen.add(num)
            if len(seen) != 9:
                return False

    return True
