import functools

def inject_attributes_decorator(cls):
    class_name = cls.__name__

    # Inject class_name into the class itself
    setattr(cls, 'class_name', class_name)

    # Iterate over all attributes of the class
    for attr_name, attr_value in cls.__dict__.items():
        # Check if the attribute is a function (method)
        if callable(attr_value) and not isinstance(attr_value, type):
            # Create a wrapper that preserves the original function's metadata
            @functools.wraps(attr_value)
            def wrapper(*args, **kwargs):
                return attr_value(*args, **kwargs)

            # Set the method_name attribute on the wrapper
            setattr(wrapper, 'method_name', attr_name)

            # Replace the original method with the wrapper in the class
            setattr(cls, attr_name, wrapper)

    return cls
