import xml.etree.ElementTree as ET

def extract_attribute_values(xml_string):
    root = ET.fromstring(xml_string)
    result = {}

    # Add root element tag and its attributes
    result[root.tag] = dict(root.attrib)

    # Recursively process all child elements
    for child in root.iter():
        if child.tag not in result:
            result[child.tag] = {}
        result[child.tag].update(child.attrib)

    return result
