def is_toeplitz(matrix):
    if not matrix or not matrix[0]:
        return True

    rows = len(matrix)
    cols = len(matrix[0])

    # Check if the matrix is square
    if rows != cols:
        return False

    # Check each diagonal
    for i in range(rows):
        for j in range(cols):
            # The value at (i, j) should equal the value at (i-1, j-1) if i>0 and j>0
            if i > 0 and j > 0:
                if matrix[i][j] != matrix[i-1][j-1]:
                    return False

    return True
