import inspect

def get_default_args(function):
    """
    Returns a dictionary mapping each argument name to its default value
    for the given function. Handles nested namespaces (e.g., module.submodule.function).
    Compatible with both Python 2 and 3.
    """
    # Normalize the function name to handle nested namespaces if needed
    # The input 'function' is expected to be a callable object, not a string.
    # If a string is passed, we attempt to resolve it from sys.modules.
    if isinstance(function, str):
        import sys
        parts = function.split('.')
        obj = sys.modules.get(parts[0])
        if obj is None:
            raise ValueError("Module not found: {}".format(parts[0]))
        for part in parts[1:]:
            obj = getattr(obj, part, None)
            if obj is None:
                raise AttributeError("Object not found: {}".format(function))
        function = obj

    if not callable(function):
        raise TypeError("Expected a callable, got {}".format(type(function)))

    # Use inspect to get the signature
    try:
        # Python 3.3+
        sig = inspect.signature(function)
    except (ValueError, TypeError):
        # Fallback for older Python versions or built-in functions
        try:
            # Python 2.7 style
            import types
            if isinstance(function, types.FunctionType):
                argspec = inspect.getargspec(function)
                defaults = argspec.defaults
                if defaults is None:
                    return {}
                # argspec.args contains all arguments, defaults align with the last N args
                all_args = argspec.args
                default_start = len(all_args) - len(defaults)
                return dict(zip(all_args[default_start:], defaults))
            else:
                return {}
        except Exception:
            return {}

    # Extract default values from the signature
    result = {}
    for name, param in sig.parameters.items():
        if param.default is not inspect.Parameter.empty:
            result[name] = param.default

    return result
