from typing import List

def check_triplet_sum(nums: List[int], t: int) -> bool:
    if len(nums) < 3:
        raise ValueError("Input list must contain at least three elements.")

    # Work on a sorted copy to avoid mutating the original list
    sorted_nums = sorted(nums)
    n = len(sorted_nums)

    for i in range(n - 2):
        left = i + 1
        right = n - 1

        while left < right:
            current_sum = sorted_nums[i] + sorted_nums[left] + sorted_nums[right]

            if current_sum == t:
                return True
            elif current_sum < t:
                left += 1
            else:
                right -= 1

    return False
