def compare_integers(n1, n2):
    def to_int(value):
        if isinstance(value, str):
            try:
                return int(value)
            except ValueError:
                raise ValueError(f"Invalid integer string: {value}")
        if isinstance(value, float):
            if not value.is_integer():
                raise ValueError(f"Float must be an integer value: {value}")
            return int(value)
        if isinstance(value, int):
            return value
        raise TypeError(f"Unsupported type for integer comparison: {type(value)}")

    try:
        i1 = to_int(n1)
        i2 = to_int(n2)
    except (ValueError, TypeError) as e:
        return f"Error: {e}"

    if i1 < i2:
        return "less"
    elif i1 > i2:
        return "greater"
    else:
