def escape_special_symbols(text: str) -> str:
    result = []
    for char in text:
        if char == '\\':
            result.append('\\\\')
        elif char == "'":
            result.append("\\'")
        elif char == '"':
            result.append('\\"')
        elif char == '\n':
            result.append('\\n')
        elif char == '\r':
            result.append('\\r')
        elif char == '\t':
            result.append('\\t')
        elif char == '\b':
            result.append('\\b')
        elif char == '\f':
            result.append('\\f')
        elif ord(char) < 32:
            result.append(f'\\u{ord(char):04x}')
        else:
            result.append(char)
    return ''.join(result)
