def handle_function_call(fn, default_args=None, **kwargs):
    if default_args is None:
        default_args = {}

    # Check for the special keyword argument
    ignore_missing = kwargs.pop('ignore_missing_args', False)

    # Get the signature of the function to determine required and optional parameters
    import inspect
    sig = inspect.signature(fn)
    params = sig.parameters

    # Determine which arguments are missing
    bound_args = sig.bind_partial(**kwargs)
    missing_args = set(bound_args.arguments.keys()) - set(kwargs.keys())

    # If not ignoring missing args, fill them with defaults
    if not ignore_missing:
        for arg_name in missing_args:
            if arg_name in params:
                param = params[arg_name]
                if param.default is not inspect.Parameter.empty:
                    kwargs[arg_name] = param.default
                else:
                    # Required argument missing, raise TypeError
                    raise TypeError(f"Missing required argument: {arg_name}")

    # Bind all arguments
    bound = sig.bind(**kwargs)
    bound.apply_defaults()

    # Call the function
    return fn(*bound.args, **bound.kwargs)
