def create_sudoku_grid():
    def is_valid(grid, row, col, num):
        # Check row
        if any(grid[row][c] == num for c in range(9)):
            return False
        # Check column
        if any(grid[r][col] == num for r in range(9)):
            return False
        # Check 3x3 subgrid
        start_row, start_col = 3 * (row // 3), 3 * (col // 3)
        for r in range(start_row, start_row + 3):
            for c in range(start_col, start_col + 3):
                if grid[r][c] == num:
                    return False
        return True

    def solve(grid):
        for row in range(9):
            for col in range(9):
                if grid[row][col] == "0":
                    for num in "123456789":
                        if is_valid(grid, row, col, num):
                            grid[row][col] = num
                            if solve(grid):
                                return True
                            grid[row][col] = "0"
                    return False
        return True

    # Initialize grid with "0" as placeholders
    grid = [["0" for _ in range(9)] for _ in range(9)]
    solve(grid)
    return grid
