def find_subsequence_with_max_sum(input_list):
    if not isinstance(input_list, list):
        raise TypeError("Input must be a list.")

    if not input_list:
        return []

    max_sum = float('-inf')
    best_subsequence = []
    current_sum = 0
    current_subsequence = []

    for num in input_list:
        if not isinstance(num, int):
            raise TypeError("All elements in the list must be integers.")

        if current_sum + num > 0:
            current_sum += num
            current_subsequence.append(num)
        else:
            if current_sum > max_sum:
                max_sum = current_sum
                best_subsequence = current_subsequence[:]
            current_sum = 0
            current_subsequence = []

    # Check after the loop in case the best subsequence ends at the last element
    if current_sum > max_sum:
        max_sum = current_sum
        best_subsequence = current_subsequence

    # Edge case: if all numbers are negative, the max subsequence is the single largest number
    if best_subsequence == [] and input_list:
        max_single = max(input_list)
        # Find the first occurrence of the max single value to maintain consistency
        for num in input_list:
            if num == max_single:
                return [num]

    return best_subsequence if best_subsequence else []
