def search_pattern_in_file(filename: str, pattern: str) -> int:
    if not pattern:
        return 0

    with open(filename, 'rb') as f:
        data = f.read()

    pattern_bytes = pattern.encode('utf-8')
    pattern_len = len(pattern_bytes)
    data_len = len(data)

    for i in range(data_len - pattern_len + 1):
        if data[i] == pattern_bytes[0]:
            match = True
            for j in range(1, pattern_len):
                if data[i + j] != pattern_bytes[j]:
                    match = False
                    break
            if match:
                return i

    return -1
```

