def hexadecimal_to_unsigned_integer(hex_str):
    if not isinstance(hex_str, str):
        return None

    hex_str = hex_str.strip()

    # Check for optional '0x' prefix
    if hex_str.startswith('0x') or hex_str.startswith('0X'):
        hex_str = hex_str[2:]

    if not hex_str:
        return None

    valid_chars = set('0123456789abcdefABCDEF')
    if not all(c in valid_chars for c in hex_str):
        return None

    result = 0
    for char in hex_str:
        if char in '0123456789':
            value = int(char)
        else:
            value = ord(char) - ord('A') + 10 if 'A' <= char <= 'F' else ord(char) - ord('a') + 10

        result = result * 16 + value

