            return acc
        if exp % 2 == 0:
            half = _tail_exp(base * base, exp // 2, acc)
        else:
            half = _tail_exp(base * base, exp // 2, acc * base)
        return half

    result = _tail_exp(x, n, 1)
    memo[(x, n)] = result
    return result
