```python
def calculate_island_boundaries(map):
    if not map or not map[0]:
        return []

    rows = len(map)
    cols = len(map[0])
    visited = [[False] * cols for _ in range(rows)]
    boundaries = []

    def dfs(r, c, value, current_boundary):
        stack = [(r, c)]
        visited[r][c] = True
        current_boundary.append((r, c))

        while stack:
            cr, cc = stack.pop()
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if not visited[nr][nc]:
                        if map[nr][nc] == value:
                            visited[nr][nc] = True
                            current_boundary.append((nr, nc))
                            stack.append((nr, nc))
                        elif map[nr][nc] == 0:
                            # Water boundary
                            pass
                    # If already visited and same value, ignore
                    # If already visited and different (non-zero), it's another island, ignore

    for r in range(rows):
        for c in range(cols):
            if not visited[r][c] and map[r][c] != 0:
                value = map[r][c]
                current_boundary = []
                dfs(r, c, value, current_boundary)
                if current_boundary:
                    # Compute bounding box
                    min_r = min(cell[0] for cell in current_boundary)
                    max_r = max(cell[0] for cell in current_boundary)
                    min_c = min(cell[1] for cell in current_boundary)
                    max_c = max(cell[1] for cell in current_boundary)
                    boundaries.append((min_r, min_c, max_r, max_c))

    return boundaries
