```python
def interval_estimate(array, v_min, v_max):
    """
    Finds indices i and j such that array[i] >= v_min and array[j] <= v_max
    using binary search. Assumes the array is sorted in ascending order.

    Returns:
        (i, j) if valid indices exist, otherwise None.
    """
    if not array:
        return None

    # Binary search for the first index i where array[i] >= v_min
    left, right = 0, len(array) - 1
    i = None
    while left <= right:
        mid = (left + right) // 2
        if array[mid] >= v_min:
            i = mid
            right = mid - 1
        else:
            left = mid + 1

    if i is None:
        return None  # No element >= v_min

    # Binary search for the last index j where array[j] <= v_max
    left, right = 0, len(array) - 1
    j = None
    while left <= right:
        mid = (left + right) // 2
        if array[mid] <= v_max:
            j = mid
            left = mid + 1
        else:
            right = mid - 1

    if j is None:
        return None  # No element <= v_max

    # Ensure i <= j; if i > j, the interval is invalid
    if i > j:
        return None

    return (i, j)
```

