        if not isinstance(value, str):
            raise TypeError(f"Value must be a string, got {type(value).__name__}")
        return value

    def format_section(section_name, data):
        lines = []
        for key, value in data.items():
            if isinstance(value, dict):
                nested_lines = format_section(key, value)
                lines.append(f"[{section_name}]{key} = {{...}}")  # Placeholder for nested structure
                lines.extend(nested_lines)
            else:
                formatted_value = format_value(value)
                lines.append(f"[{section_name}]{key} = {formatted_value}")
        return lines

    def format_settings(data):
