def compose_ops(ops, *args, **kwargs):
    if not ops:
        raise ValueError("The list of operators 'ops' cannot be empty.")

    if len(args) + len(kwargs) != 1:
        raise ValueError("Exactly one argument (positional or keyword) is expected.")

    # Determine the single argument to pass through the composed functions
    if args:
        value = args[0]
    else:
        if kwargs:
            key = next(iter(kwargs))
            value = kwargs[key]
            # Remove the used keyword argument to avoid passing it further
            kwargs.pop(key)
        else:
            raise ValueError("No argument provided.")

    # Compose the unary operators from left to right
    result = value
    for op in ops:
        result = op(result)

    return result
