def check_string_to_int(string):
    if not isinstance(string, str):
        return None

    s = string.strip()
    if not s:
        return None

    i = 0
    n = len(s)

    # Handle optional sign
    if i < n and s[i] in '+-':
        sign = -1 if s[i] == '-' else 1
        i += 1
    else:
        sign = 1

    if i == n:
        return None

    digits = []
    valid = True

    while i < n:
        c = s[i]
        if c.isdigit():
            digits.append(c)
            i += 1
        else:
            valid = False
            break

    if not valid or not digits:
        return None

    # Convert digits to integer manually
    value = 0
    for d in digits:
        value = value * 10 + (ord(d) - ord('0'))

    value *= sign

    if value == 0:
        return "0"

    if value > 0:
        # Positive: string of 0s for each valid digit
        return "0" * len(digits)
    else:
        # Negative: string of 1s for each valid digit + "0" for sign
        return "1" * len(digits) + "0"
