def dist_between_points(point1, point2):
    # Validate point1
    if not isinstance(point1, dict):
        raise ValueError("point1 must be a dictionary")
    if 'x' not in point1 or 'y' not in point1:
        raise ValueError("point1 must contain 'x' and 'y' keys")
