def propagate_labels(root, label):
    if root is None:
        return root

    # If the root already has a label, we still need to propagate to descendants
    # unless the problem implies stopping if root is labeled. 
    # Based on "If a node already has a label, it should not be re-labeled",
    # we only skip setting the label if it's already set, but continue traversal.

    def dfs(node):
        if node is None:
            return

        # Set label only if not already set
        if not hasattr(node, 'label') or node.label is None:
            node.label = label

        # Recursively visit children
        if hasattr(node, 'children'):
            for child in node.children:
                dfs(child)
        elif hasattr(node, 'left') and hasattr(node, 'right'):
            dfs(node.left)
            dfs(node.right)

    dfs(root)
    return root
