def binary_search_recursive(data, target):
    # Validate input: ensure data is a list of integers and is sorted
    if not isinstance(data, list):
        raise TypeError("data must be a list")
    if not all(isinstance(x, int) for x in data):
        raise TypeError("All elements in data must be integers")
    if data != sorted(data):
        raise ValueError("data must be a sorted list")

    def _helper(left, right):
        if left > right:
            return -1

        mid = (left + right) // 2
        if data[mid] == target:
            return mid
        elif data[mid] < target:
            return _helper(mid + 1, right)
        else:
            return _helper(left, mid - 1)

    return _helper(0, len(data) - 1)
