def parse_cidr_range(cidr_range, default_value=None):
    try:
        if '/' not in cidr_range:
            return default_value

        network, prefix_len = cidr_range.split('/')
        prefix_len = int(prefix_len)

        if prefix_len < 0 or prefix_len > 32:
            return default_value

        ip_obj = int(network, 16)
        if prefix_len == 0:
            return default_value

        first_ip = ip_obj << (32 - prefix_len)
        return str(int(first_ip) & 0xFFFFFFFF)
    except Exception:
        return default_value
