def has_cycle(graph, visited=None, parent=None, node=None):
    """
    Detects if an undirected graph contains a cycle using a recursive DFS approach.

    Args:
        graph: List of edges, where each edge is a tuple (u, v)
        visited: Set of visited nodes (internal use)
        parent: Parent node in the DFS tree (internal use)
        node: Current node being visited (internal use)

    Returns:
        bool: True if a cycle exists, False otherwise
    """
    if visited is None:
        visited = set()

    # Build adjacency list from edge list
    if node is None:
        # First call: build graph and start DFS from first node
        adj = {}
        for u, v in graph:
            if u not in adj:
                adj[u] = []
            if v not in adj:
                adj[v] = []
            adj[u].append(v)
            adj[v].append(u)

        if not adj:
            return False

        # Start DFS from the first node
        return _dfs_cycle(adj, visited, None, next(iter(adj.keys())))

    # Recursive DFS helper
    visited.add(node)

    for neighbor in adj.get(node, []):
        if neighbor == parent:
            continue
        if neighbor in visited:
            return True
        if _dfs_cycle(adj, visited, node, neighbor):
            return True

    return False

def _dfs_cycle(adj, visited, parent, node):
    """Internal recursive helper for cycle detection."""
    visited.add(node)

    for neighbor in adj.get(node, []):
        if neighbor == parent:
            continue
        if neighbor in visited:
            return True
        if _dfs_cycle(adj, visited, node, neighbor):
            return True

    return False
