from typing import List, Dict, Optional

def get_signal_status(detectors: List[Dict], signal_id: str) -> str:
    """
    Determine the status of a detector for a given signal ID based on:
    1. Active detectors are "active".
    2. Inactive detectors with a valid previous detector inherit the previous status.
    3. Inactive detectors without a valid previous detector are "inactive".

    A detector is considered valid if it is a non-None dictionary.
    """
    # Build a lookup map from signal_id to detector dict
    detector_map: Dict[str, Dict] = {}
    for det in detectors:
        if det is not None and isinstance(det, dict):
            signal_id_key = det.get("signal_id")
            if signal_id_key is not None:
                detector_map[signal_id_key] = det

    # If the requested signal_id is not found, return "inactive"
    if signal_id not in detector_map:
        return "inactive"

    # Compute statuses in topological order (by dependency chain)
    # We'll use a memoization dict to store computed statuses
    status_cache: Dict[str, str] = {}

    def compute_status(det: Dict[str, Optional[Dict]]) -> str:
        signal_id_key = det.get("signal_id")
        if signal_id_key not in status_cache:
            is_active = det.get("active", False)
            if is_active:
                status_cache[signal_id_key] = "active"
            else:
                prev_det = det.get("previous")
                if prev_det is not None and isinstance(prev_det, dict):
                    prev_status = compute_status(prev_det)
                    status_cache[signal_id_key] = prev_status
                else:
                    status_cache[signal_id_key] = "inactive"
        return status_cache[signal_id_key]

    return compute_status(detector_map[signal_id])
