def check_type_and_size(x, t, size=None):
    # Check if x is of type t
    if not isinstance(x, t):
        # If x is not of type t, raise TypeError as per spec
        raise TypeError(f"Expected type {t.__name__}, got {type(x).__name__}")

    # If size is provided, validate it
    if size is not None:
        if not isinstance(size, int) or size <= 0:
            raise ValueError("size must be a positive integer")

    # If x is a string and size is provided, return x repeated size times
    if isinstance(x, str) and size is not None:
        return x * size

    # If x is a list and size is provided, return a list of size copies of x
    if isinstance(x, list) and size is not None:
        return [x] * size

    # If x is neither a string nor a list, or size is not provided, return x directly
    return x
