def precision(confusion_matrix):
    # Validate input is a list of lists with 2 rows and 2 columns
    if not isinstance(confusion_matrix, list) or len(confusion_matrix) != 2:
        raise ValueError("Confusion matrix must be a 2x2 matrix.")

    for row in confusion_matrix:
        if not isinstance(row, list) or len(row) != 2:
            raise ValueError("Confusion matrix must be a 2x2 matrix.")

        for cell in row:
            if not isinstance(cell, (int, float)):
                raise ValueError("All cells in the confusion matrix must contain numeric values.")

    # Extract values based on the specification:
    # Rows: Actual labels, Columns: Predicted labels
    # Top-left (0,0): True Positives (TP)
    # Top-right (0,1): False Positives (FP)
    # Bottom-left (1,0): False Negatives (FN)
    # Bottom-right (1,1): True Negatives (TN)

    tp = confusion_matrix[0][0]
    fp = confusion_matrix[0][1]

    # Precision = TP / (TP + FP)
    # Handle division by zero case
    if tp + fp == 0:
        return 0.0

    return tp / (tp + fp)
