from typing import List, Callable, Tuple, Iterable

def partition(data: Iterable, predicate: Callable[[Any], bool]) -> Tuple[List, List]:
    """
    Partitions the input iterable into two lists based on the predicate.
    Uses lazy evaluation by returning generators for both lists.
    Does not modify the original data.

    Args:
        data: An iterable of elements.
        predicate: A function that takes an element and returns True or False.

    Returns:
        A tuple (true_list, false_list) where both are lazy generators.
    """
    def true_generator():
        for item in data:
            if predicate(item):
                yield item

    def false_generator():
        for item in data:
            if not predicate(item):
                yield item

    return true_generator(), false_generator
```

