import os

def file_size_mapping(directory):
    """
    Recursively traverses a directory tree and returns a dictionary mapping
    file sizes to lists of file paths.

    Args:
        directory (str): Path to the root directory.

    Returns:
        dict: {file_size: [list of file paths]}
    """
    result = {}

    def traverse(path):
        try:
            entries = os.listdir(path)
        except PermissionError:
            return

        for entry in entries:
            full_path = os.path.join(path, entry)

            if os.path.isfile(full_path):
                size = os.path.getsize(full_path)
                if size not in result:
                    result[size] = []
                result[size].append(full_path)
            elif os.path.isdir(full_path):
                traverse(full_path)

    traverse(directory)
    return result
```

