import csv

def convert_csv_to_dict(csv_file):
    """
    Reads a CSV file and returns a dictionary of lists.

    Keys are column headers from the first row.
    Values are lists containing the data for each column (one item per row).
    Missing values are represented as None.

    Args:
        csv_file (str): Path to the CSV file.

    Returns:
        dict: Dictionary mapping column headers to lists of values.
    """
    result = {}

    with open(csv_file, mode='r', newline='', encoding='utf-8') as file:
        reader = csv.reader(file)

        # Read header row
        try:
            headers = next(reader)
        except StopIteration:
            return {}

        # Initialize lists for each column
        for header in headers:
            result[header] = []

        # Read data rows
        for row in reader:
            for i, header in enumerate(headers):
                if i < len(row):
                    result[header].append(row[i])
                else:
                    result[header].append(None)

    return result
