import types

class VersionMeta(type):
    """
    Metaclass that implements software versioning conventions with integer versions.
    Provides a class-level 'version' attribute.
    """
    _version = 1

    def __new__(mcs, name, bases, namespace):
        cls = super().__new__(mcs, name, bases, namespace)
        # Ensure version is an integer
        if not isinstance(cls._version, int):
            raise TypeError("Version must be an integer.")
        return cls

    @classmethod
    def get_version(cls):
        return cls._version

    def __getattr__(cls, name):
        if name == "version":
            return cls.get_version()
        raise AttributeError(f"type object '{cls.__name__}' has no attribute '{name}'")

def create_class(class_name, attributes):
    """
    Dynamically creates a class with a specified name and given attributes.
    The class uses VersionMeta as its metaclass.

    Args:
        class_name (str): The name of the class to create.
        attributes (dict): A dictionary of attribute names and values.

    Returns:
        type: The dynamically created class.
    """
    # Set a default version if not provided in attributes
    if "_version" not in attributes:
        attributes["_version"] = 1

    # Ensure _version is an integer
    if not isinstance(attributes["_version"], int):
        raise ValueError("The '_version' attribute must be an integer.")

    # Create the class with the specified metaclass
    return type(class_name, (object,), attributes, metaclass=VersionMeta)
