    Returns:
        dict: A dictionary containing the parsed XML data.

    Raises:
        ValueError: If the XML is empty, malformed, or missing required root tags.
        TypeError: If the input is not a string.
    """
    if not isinstance(xml_str, str):
        raise TypeError("Input must be a string.")

    if not xml_str.strip():
        raise ValueError("XML string is empty.")

    try:
        root = ET.fromstring(xml_str)
    except ET.ParseError as e:
        raise ValueError(f"Invalid XML syntax: {e}") from e

    if root is None:
        raise ValueError("XML parsing failed: no root element found.")

    def element_to_dict(element: ET.Element) -> Dict[str, Any]:
        """Recursively convert an XML element to a dictionary."""
        node = {}

        # Add text content if present and not just whitespace
        if element.text and element.text.strip():
            node['text'] = element.text.strip()

        # Add attributes if present
        if element.attrib:
            node['attributes'] = element.attrib

        # Process child elements
        children = {}
        for child in element:
            child_dict = element_to_dict(child)
            # Handle multiple children with the same tag name
            tag = child.tag
            if tag in children:
                if not isinstance(children[tag], list):
                    children[tag] = [children[tag]]
                children[tag].append(child_dict)
            else:
                children[tag] = child_dict

        if children:
            node['children'] = children

        return node if node else {}

    result = element_to_dict(root)

    # Ensure the result is not an empty dictionary for a valid root
    if not result:
        raise ValueError("Parsed XML resulted in an empty dictionary.")

    return result
```

