    user_map = {}
    for user in users:
        user_id = user.get('id')
        if user_id is None:
            user_id = len(user_map)
            user['id'] = user_id
        user_map[user_id] = user

    # Build booking lookup by (user_id, booking_id)
    booking_map = {}
    user_bookings = {uid: [] for uid in user_map}

    for booking in bookings:
        user_id = booking.get('user_id')
        booking_id = booking.get('id')
        if user_id is None or booking_id is None:
            continue  # Skip invalid bookings

        if user_id not in user_map:
            continue  # Skip bookings for non-existent users

        if booking_id not in booking_map:
            booking_map[(user_id, booking_id)] = booking
        else:
            # If duplicate, keep the first one or update? Here we keep first.
            pass

        user_bookings[user_id].append(booking)

    return {
        'users': list(user_map.values()),
        'bookings': list(booking_map.values()),
        'user_bookings': {
            str(uid): [b for b in user_bookings.get(uid, [])]
            for uid in user_map
        }
    }
