import json
import unittest

def convert_to_json(data, indent=None):
    """
    Converts a nested dictionary of arbitrary depth to a JSON string.
    Non-primitive data types (e.g., lists, dicts, sets, custom objects) are ignored 
    by converting them to None or skipping them if they are not primitive.

    However, since JSON supports lists and dicts, we interpret "non-primitive" as 
    excluding complex types like sets, custom objects, etc. Lists and dicts are 
    considered valid JSON structures.

    If a value is not JSON serializable (e.g., set, datetime, custom object), 
    it will be converted to None.

    Parameters:
        data (any): The input data to convert.
        indent (int, optional): Number of spaces for indentation. Defaults to None (compact).

    Returns:
        str: JSON string representation of the data.
    """
    def serialize(obj):
        if isinstance(obj, dict):
            return {k: serialize(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [serialize(item) for item in obj]
        elif isinstance(obj, set):
            return None  # Sets are not JSON serializable
        elif isinstance(obj, (str, int, float, bool, type(None))):
            return obj
        else:
            return None  # Custom objects or other types become None

    serialized_data = serialize(data)
    return json.dumps(serialized_data, indent=indent)


class TestConvertToJson(unittest.TestCase):
    def test_simple_dict(self):
        data = {"name": "Alice", "age": 30}
        result = convert_to_json(data)
        self.assertEqual(result, '{"name": "Alice", "age": 30}')

    def test_nested_dict(self):
        data = {"user": {"name": "Bob", "age": 25}, "active": True}
        result = convert_to_json(data)
        self.assertIn('"user":', result)
        self.assertIn('"name": "Bob"', result)

    def test_with_indent(self):
        data = {"a": 1, "b": {"c": 2}}
        result = convert_to_json(data, indent=4)
        self.assertIn("    ", result)

