def flow_balance(network):
    """
    Computes the flow balance of a network represented by a dictionary.

    The network is a dictionary where:
      - keys are nodes
      - values are lists of outgoing neighbor nodes

    Returns a dictionary of dictionaries:
      - outer keys are nodes
      - each value is {'in': {incoming_node: flow}, 'out': {outgoing_node: flow}}

    Flow values are assumed to be 1 for each edge.
    """
    # Collect all nodes (including those that only appear as destinations)
    all_nodes = set(network.keys())
    for neighbors in network.values():
        all_nodes.update(neighbors)

    result = {}

    # Precompute incoming edges for efficiency
    incoming = {node: [] for node in all_nodes}
    for node, neighbors in network.items():
        for neighbor in neighbors:
            incoming[neighbor].append(node)

    for node in all_nodes:
        # Outgoing flows
        out_flows = {}
        if node in network:
            for neighbor in network[node]:
                out_flows[neighbor] = 1

        # Incoming flows
        in_flows = {}
        for source in incoming[node]:
            in_flows[source] = 1

        result[node] = {
            'in': in_flows,
            'out': out_flows
        }

    return result
