def multiply_without_star(a, b):
    # Handle sign
    negative = (a < 0) ^ (b < 0)
    a, b = abs(a), abs(b)

    # Recursive multiplication using addition
    def multiply(x, y):
        if y == 0:
            return 0
        if y == 1:
            return x
        # Use bit shifting for efficiency: y = 2*k + r
        if y & 1:
            return x + multiply(x, y - 1)
        else:
            half = multiply(x, y >> 1)
            return half + half

    result = multiply(a, b)
    return -result if negative else result
