    """
    Converts a hierarchical dictionary into a flat dictionary.
    If a key is encountered multiple times, values are merged into a list.

    Args:
        data (dict): The hierarchical dictionary to flatten.

    Returns:
        dict: A flat dictionary with merged values as lists where duplicates exist.
    """
    flat_dict = {}

    def _flatten(current_dict, prefix=""):
        for key, value in current_dict.items():
            new_key = f"{prefix}.{key}" if prefix else key

            if isinstance(value, dict):
                _flatten(value, new_key)
            else:
