import re

def correct_function_name(function_name):
    if not function_name:
        return function_name

    # Check if the first character is uppercase
    if function_name[0].isupper():
        # If the first character is uppercase, the rest should be lowercase
        # unless there are already uppercase letters indicating camelCase
        if len(function_name) > 1 and function_name[1].isupper():
            # Pattern like "CamelCase" -> keep as is if it's already proper camelCase starting with uppercase
            # But standard camelCase starts with lowercase, so "CamelCase" is PascalCase
            # We'll convert to camelCase by making the first letter lowercase
            return function_name[0].lower() + function_name[1:]
        else:
            # All lowercase after first char -> convert to camelCase by lowercasing everything
            return function_name[0].lower() + function_name[1:]
    else:
        # First character is lowercase, check if it's all lowercase (incorrect)
        # or if it's already camelCase
        if function_name == function_name.lower():
            # All lowercase, need to capitalize the first letter of each word
            # Split by lowercase-to-uppercase transitions
            words = re.findall(r'[a-z]+|[A-Z][a-z]*', function_name)
            if words:
                return words[0].lower() + ''.join(word.capitalize() for word in words[1:])
            else:
                return function_name.lower()
        else:
            # Already has mixed case, likely correct camelCase
            return function_name
