def remove_range(lst, start, end):
    # Normalize indices to handle negative values
    n = len(lst)
    if n == 0:
        return lst[:]

    # Adjust negative indices
    if start < 0:
        start = n + start
    if end < 0:
        end = n + end

    # Clamp indices to valid range [0, n]
    start = max(0, min(start, n))
    end = max(0, min(end, n))

    # Ensure start <= end for slicing logic; if start > end, remove nothing
    if start > end:
        return lst[:]

    # Return a new list with the specified range removed
    return lst[:start] + lst[end:]
