import ast

def extract_variable_and_value(string):
    try:
        tree = ast.parse(string)
        if not tree.body:
            return None
        # Expect a single assignment statement
        if not isinstance(tree.body[0], ast.Assign):
            return None
        assign = tree.body[0]
        if len(assign.targets) != 1:
            return None
        target = assign.targets[0]
        if not isinstance(target, ast.Name):
            return None
        var_name = target.id
        if not isinstance(assign.value, ast.Constant):
