def detect_cycle(graph):
    # Build adjacency list and track visited nodes
    visited = {}
    rec_stack = set()  # To track nodes in the current recursion stack

    def has_cycle(node):
        if node in rec_stack:
            return True
        if node in visited:
            return False

        visited[node] = True
        rec_stack.add(node)

        # Get neighbors
        neighbors = graph.get(node, [])
        for neighbor in neighbors:
            if has_cycle(neighbor):
                return True

        rec_stack.remove(node)
        return False

    # Ensure all nodes are considered, even if they have no outgoing edges
    all_nodes = set()
    for u, v in graph:
        all_nodes.add(u)
        all_nodes.add(v)

    for node in all_nodes:
        if node not in visited:
            if has_cycle(node):
                return True

    return False
