class Node:
    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def insert(self, key, value):
        # Insert at the head for O(1) insertion
        new_node = Node(key, value)
        new_node.next = self.head
        self.head = new_node

    def remove(self, key):
        # Remove the first node with the given key
        current = self.head
        prev = None
        while current:
            if current.key == key:
                if prev:
                    prev.next = current.next
                else:
                    self.head = current.next
                return True
            prev = current
            current = current.next
        return False

def hash_constructor(pairs):
    # Determine table size (power of 2 for simplicity, at least 1)
    size = 1
    while size <= len(pairs):
        size *= 2
    if size == 0:
        size = 1

    # Initialize buckets
    buckets = [LinkedList() for _ in range(size)]

    # Simple hash function
    def hash(key):
        return hash(key) % size

    # Build the hash table
    for key, value in pairs:
        index = hash(key)
        buckets[index].insert(key, value)

    return buckets
