def get_code_dict(root, binary_code=''):
    if root is None:
        return {}

    result = {}

    # If we reach a leaf node (both children are None), store the code
    if root.left is None and root.right is None:
        result[root.value] = binary_code
        return result

    # Append '0' for left child, '1' for right child
    if root.left:
