        hours = int(time_string[0:2])
        minutes = int(time_string[3:5])
        seconds = int(time_string[6:8])
    except ValueError:
        return -1

    # Validate ranges
    if not (0 <= hours <= 23 and 0 <= minutes <= 59 and 0 <= seconds <= 59):
        return -1

    return hours * 3600 + minutes * 60 + seconds
```

