```python
def parse_and_cast_to_type(s, target_type):
    if target_type is bool:
        if isinstance(s, str):
            s_lower = s.lower()
            if s_lower == "true":
                return True
            elif s_lower == "false":
                return False
            else:
                return None
        elif isinstance(s, (int, float)):
            if s == 1 or s == 1.0:
                return True
            elif s == 0 or s == 0.0:
                return False
            else:
                return None
        else:
            return None

    if target_type is int:
        try:
            # Handle strings that represent integers
            if isinstance(s, str):
                # Check if it's a valid integer string (optional sign, digits only)
                if not s.lstrip('-+').isdigit():
                    return None
                return int(s)
            elif isinstance(s, float):
                if s.is_integer():
                    return int(s)
                else:
                    return None
            elif isinstance(s, int):
                return s
            else:
                return None
        except (ValueError, AttributeError):
            return None

    if target_type is float:
        try:
            if isinstance(s, str):
                # Check if it's a valid float string
                if not s.replace('.', '', 1).lstrip('-+').isdigit() and not (s.startswith('-') or s.startswith('+')):
                    # Additional check for cases like "1.2.3" or "1e2"
                    float(s)
                else:
                    return float(s)
            elif isinstance(s, int):
                return float(s)
            elif isinstance(s, float):
                return s
            else:
                return None
        except (ValueError, AttributeError):
            return None

    if target_type is str:
        if isinstance(s, str):
            return s
        elif isinstance(s, (int, float)):
            return str(s)
        else:
            return str(s)

    return None
```

