def check_valid_ip(ip):
    # Precondition check: input must not be an empty string
    if not ip:
        return False

    parts = ip.split('.')
    if len(parts) != 4:
        return False

    for part in parts:
        # Check for empty part (e.g., "1.2.3.")
        if not part:
            return False

        # Check for leading zeros: invalid if length > 1 and starts with '0'
        if len(part) > 1 and part[0] == '0':
            return False

        # Check if all characters are digits
        if not part.isdigit():
            return False

        # Check numeric range
        num = int(part)
        if num < 0 or num > 255:
            return False

    return True
