def get_value_from(data, key, default=None):
    if isinstance(data, dict):
        return data.get(key, default)
    elif isinstance(data, list):
        # For a list, interpret 'key' as an index if it's an integer,
        # otherwise search for a dictionary within the list that has the key.
        if isinstance(key, int):
            if 0 <= key < len(data):
                return data[key]
            return default
        else:
            # Search for a dict in the list with the given key
            for item in data:
                if isinstance(item, dict) and key in item:
                    return item[key]
            return default
    else:
        # If data is neither a list nor a dict, return default
        return default
