def get_largest_int_from_string(s):
    import re

    # Split the string by whitespace to get potential number tokens
    tokens = s.split()

    if not tokens:
        raise ValueError("Input string is empty or contains no numbers.")

    numbers = []
    for token in tokens:
        # Check if the token consists only of digits (allowing optional leading minus for negative numbers)
        if token.startswith('-') and len(token) > 1 and token[1:].isdigit():
            numbers.append(int(token))
        elif token.isdigit():
            numbers.append(int(token))
        else:
            # Contains non-numeric characters (other than optional leading minus for negatives)
            raise ValueError(f"Invalid character found in token: '{token}'")

    if not numbers:
        raise ValueError("No valid integers found in the string.")

    return max(numbers)
```

